INSERT INTO `tb_contratti_revisioni` VALUES
(1,1,1,'Rev.1','Invio manuale da timeline.','Alex Olivieri','{\"detail\":{\"contratto\":{\"id_contratto\":1,\"id_anagrafica\":1,\"codice\":\"cp-01\",\"titolo\":\"prova contratto 1\",\"testo_legale\":\"<p><i>*Per le ispezioni per le quali si rende necessario l‚Äôinvio della seconda\\nraccomandata il costo della verifica √® aumentato di ‚Ç¨ 5,00, mentre se si rende\\nnecessario anche l‚Äôinvio della terza raccomandata il costo √® aumentato di\\nulteriori ‚Ç¨ 5,00 (tot. 10,00 euro). Quindi le spese postali sopra evidenziate\\nsaranno a carico degli utenti e saranno sommate alla tariffa di ispezione.<\\/i><i><\\/i><\\/p><p>Si informa altres√¨ la S.V.\\nche, laddove il pagamento non venga effettuato entro i termini indicati\\nsull‚Äôavviso di pagamento allegato, l\'Amministrazione Provinciale attiver√† la\\nprocedura di riscossione coattiva delle somme dovute.<\\/p><p>Qualora sia\\nin possesso della documentazione attestante l‚Äôeffettiva certificazione del Suo\\nimpianto per il periodo indicato, potr√† richiedere l‚Äôannullamento mediante il\\nmodulo allegato alla presente.<\\/p>\\n\\n<p>La\\nsuddetta documentazione deve essere trasmessa a mezzo Raccomandata A\\/R\\nindirizzata a: O.P.S. S.p.A. ‚Äì Via Padre Ugo Frasca snc, 66100 Chieti, oppure a\\nmezzo PEC all‚Äôindirizzo: <u>opschieti@pec.aruba.it<\\/u>, oppure consegnata a mano presso gli uffici della Societ√†\\nall‚Äôindirizzo sopra riportato, dal luned√¨ al venerd√¨ dalle ore 9.00 alle ore\\n13.00.<\\/p>\\n<p>Per qualsiasi informazione e\\/o\\nchiarimento in merito, la S.V. potr√† rivolgersi presso gli uffici della O.P.S.\\nS.p.A. cui la Provincia di Chieti ha affidato le attivit√† di ispezione degli\\nimpianti termici ai sensi della legislazione vigente.<\\/p>\\n<!--EndFragment-->\",\"data_inizio\":\"2025-12-21\",\"data_fine\":\"2026-12-20\",\"rinnovo_automatico\":1,\"attivo\":1,\"stato_code\":\"inviato\",\"stato_label\":\"Inviato\",\"created_at\":\"2025-12-23 17:04:26\",\"updated_at\":\"2025-12-23 17:27:51\",\"ragione_sociale\":\"MEDIAPRINT SRL\"},\"righe\":[{\"id_riga\":17,\"id_contratto\":1,\"tipo_item\":\"prodotto\",\"id_prodotto\":11,\"id_pacchetto\":null,\"combo_key\":null,\"descrizione\":\"Posta Massiva - Peso: Fino a 20 gr ; Tipo Spedizione: Omologato ; Destinazione: AM\",\"prezzo_unitario\":0.34,\"iva\":0,\"id_sdi_natura_iva\":1,\"sconto_base\":0,\"posizione\":1,\"sconti\":[]},{\"id_riga\":18,\"id_contratto\":1,\"tipo_item\":\"prodotto\",\"id_prodotto\":11,\"id_pacchetto\":null,\"combo_key\":null,\"descrizione\":\"Posta Massiva - Peso: Fino a 20 gr ; Tipo Spedizione: Omologato ; Destinazione: CP\",\"prezzo_unitario\":0.52,\"iva\":0,\"id_sdi_natura_iva\":1,\"sconto_base\":0,\"posizione\":2,\"sconti\":[]},{\"id_riga\":19,\"id_contratto\":1,\"tipo_item\":\"prodotto\",\"id_prodotto\":11,\"id_pacchetto\":null,\"combo_key\":null,\"descrizione\":\"Posta Massiva - Peso: Fino a 20 gr ; Tipo Spedizione: Omologato ; Destinazione: EU\",\"prezzo_unitario\":0.65,\"iva\":0,\"id_sdi_natura_iva\":1,\"sconto_base\":0,\"posizione\":3,\"sconti\":[]},{\"id_riga\":20,\"id_contratto\":1,\"tipo_item\":\"prodotto\",\"id_prodotto\":20,\"id_pacchetto\":null,\"combo_key\":null,\"descrizione\":\"Posta 4 (internazionale) - Peso: Fino a 20 gr ; Destinazione: EX Zona 1\",\"prezzo_unitario\":1.35,\"iva\":0,\"id_sdi_natura_iva\":1,\"sconto_base\":0,\"posizione\":4,\"sconti\":[]},{\"id_riga\":21,\"id_contratto\":1,\"tipo_item\":\"prodotto\",\"id_prodotto\":20,\"id_pacchetto\":null,\"combo_key\":null,\"descrizione\":\"Posta 4 (internazionale) - Peso: Fino a 20 gr ; Destinazione: EX Zona 2\",\"prezzo_unitario\":2.55,\"iva\":0,\"id_sdi_natura_iva\":1,\"sconto_base\":0,\"posizione\":5,\"sconti\":[]},{\"id_riga\":22,\"id_contratto\":1,\"tipo_item\":\"prodotto\",\"id_prodotto\":20,\"id_pacchetto\":null,\"combo_key\":null,\"descrizione\":\"Posta 4 (internazionale) - Peso: Fino a 20 gr ; Destinazione: EX Zona 3\",\"prezzo_unitario\":3.35,\"iva\":0,\"id_sdi_natura_iva\":1,\"sconto_base\":0,\"posizione\":6,\"